118	/* Sampling jitter target from DESIGN.md ("Sampling jitter": p99 < 10 ms). */
119	#define JITTER_P99_LIMIT_US 10000
120	
121	static int64_t mono_us(void)
122	{
123	    struct timespec t;
124	    clock_gettime(CLOCK_MONOTONIC, &t);
125	    return (int64_t)t.tv_sec * 1000000 + t.tv_nsec / 1000;
126	}
