165	    int64_t period_us = (int64_t)period_ms * 1000;
166	    int64_t start = mono_us() + period_us;
167	    int64_t prev = 0, ivl_min = INT64_MAX, ivl_max = 0, ivl_sum = 0;
168	    uint32_t raw_min = UINT32_MAX, raw_max = 0;
169	    double lux_sum = 0;
170	    int errors = 0, good = 0;
171	
172	    printf("      sampling %d x %ld ms (cover the sensor / shine a light to see lux follow)\n",
173	           n, period_ms);
174	    printf("      %4s %10s %7s %9s %8s\n", "i", "t_ms", "raw", "lux", "dev_us");
175	
176	    for (int i = 0; i < n; i++) {
177	        int64_t deadline = start + i * period_us;
178	        sleep_until_us(deadline);
179	        int64_t now = mono_us();
180	        dev_us[i] = now - deadline;   /* >= 0: wake-ups are never early */
181	
182	        if (i > 0) {
183	            int64_t ivl = now - prev;
184	            ivl_min = ivl < ivl_min ? ivl : ivl_min;
