199	        raw_max = raw > raw_max ? raw : raw_max;
200	        lux_sum += gt_light_raw_to_lux(raw);
201	        printf("      %4d %10.1f %7u %9.1f %8lld\n", i, t_ms, (unsigned)raw,
202	               gt_light_raw_to_lux(raw), (long long)dev_us[i]);
203	    }
