1	/* storage_feed: a load generator standing in for the hub on storage.sock
2	 * (DESIGN.md Evaluation plan, Test tooling: "writes synthetic records into
3	 * storage.sock at a set rate").
4	 *
5	 * Purpose: drive storage_main before the hub exists. It connects, reads
6	 * the seq_resume reply, and sends `count` light DATA records continuing
7	 * from the next seq, exactly as a freshly started hub will (gt_next_seq):
8	 * seq resume + 1 onward, or 0 on an empty log. It prints the reply and
9	 * what it sent, so a run shows whether storage kept every record across
10	 * a SIGTERM restart (the reply continues where the last run ended) or a
11	 * kill -9 (the reply is the last committed seq; a fresh sender continues
12	 * from there, so the lost seqs are simply reused, not marked as a GAP).
13	 *
14	 * stdout is line-buffered, so each line reaches a file or pipe as soon
15	 * as it is printed (a script can read the reply while the feed runs).
16	 *
17	 * Linux model: an AF_UNIX SOCK_SEQPACKET client, so each send() is one
18	 * whole 24 B record. MSG_NOSIGNAL turns a storage that went away into an
19	 * error instead of a SIGPIPE.
20	 *
21	 * With -r it acts as a hub that keeps running while storage restarts:
22	 * when a send fails it prints "storage gone after seq K", reconnects
23	 * every 100 ms, and continues from max(own next seq, reply + 1), so seqs
24	 * a kill -9 lost leave a hole that storage covers with a GAP (PF-03).
25	 * COUNT is then the total over all connections, and 0 means no limit.
26	 * SIGTERM / SIGINT stop the feed cleanly: it still prints its final
27	 * "sent N records, seq A..B" line (exit 0 with -r).
28	 *
29	 * Usage: storage_feed [-r] /run/plantpi/storage.sock COUNT [RATE_HZ]
30	 *   RATE_HZ defaults to 10; 0 sends as fast as possible. */
31	#include <errno.h>
32	#include <poll.h>
33	#include <signal.h>
34	#include <stdio.h>
35	#include <stdlib.h>
36	#include <string.h>
37	#include <sys/socket.h>
38	#include <sys/un.h>
39	#include <time.h>
40	#include <unistd.h>
41	
42	#include "log_record.h"
43	#include "storage_proto.h"
44	
45	#define REPLY_WAIT_MS 2000
46	
47	/* Set by SIGTERM / SIGINT. sig_atomic_t is the integer type a signal
48	 * handler may safely write; volatile makes the loop re-read it each pass. */
49	static volatile sig_atomic_t stop_requested = 0;
50	
51	/* Only sets the flag: printing or closing here would not be signal-safe. */
52	static void on_stop(int signo)
53	{
54	    (void)signo;
55	    stop_requested = 1;
56	}
57	
58	/* Parse a whole non-negative decimal number. Returns 1 on success. */
59	static int parse_count(const char *text, unsigned long *value_out)
60	{
61	    char *end = NULL;
62	    errno = 0;
63	    unsigned long value = strtoul(text, &end, 10);
64	    if (errno != 0 || end == text || *end != '\0' || text[0] == '-') {
65	        return 0;
66	    }
67	    *value_out = value;
68	    return 1;
69	}
70	
71	/* Connect to storage.sock. Returns the fd, or -1 after printing why
72	 * (unless quiet is set). */
73	static int connect_storage(const char *path, int quiet)
74	{
75	    struct sockaddr_un addr;
76	    memset(&addr, 0, sizeof addr);
77	    if (strlen(path) >= sizeof addr.sun_path) {
78	        fprintf(stderr, "storage_feed: socket path too long\n");
79	        return -1;
80	    }
81	    addr.sun_family = AF_UNIX;
82	    memcpy(addr.sun_path, path, strlen(path) + 1);
83	    int fd = socket(AF_UNIX, SOCK_SEQPACKET, 0);
84	    if (fd < 0 || connect(fd, (const struct sockaddr *)&addr, sizeof addr) != 0) {
85	        if (!quiet) {
86	            fprintf(stderr, "storage_feed: %s: %s\n", path, strerror(errno));
87	        }
88	        if (fd >= 0) {
89	            close(fd);
90	        }
91	        return -1;
92	    }
93	    return fd;
94	}
95	
96	/* Wait for and decode the seq_resume reply. Returns 1 on success. */
97	static int read_resume(int fd, gt_resume *resume)
98	{
99	    struct pollfd wait_for = { .fd = fd, .events = POLLIN, .revents = 0 };
100	    uint8_t reply[GT_RESUME_SIZE + 1];
101	    if (poll(&wait_for, 1, REPLY_WAIT_MS) != 1) {
102	        fprintf(stderr, "storage_feed: no seq_resume reply within %d ms\n", REPLY_WAIT_MS);
103	        return 0;
104	    }
105	    ssize_t got = recv(fd, reply, sizeof reply, 0);
106	    if (got != GT_RESUME_SIZE || gt_resume_decode(reply, resume) != GT_OK) {
107	        fprintf(stderr, "storage_feed: bad seq_resume reply (%ld bytes)\n", (long)got);
108	        return 0;
109	    }
110	    return 1;
111	}
112	
113	/* Connect, read seq_resume, pick the next seq with gt_next_seq and print
114	 * the usual "seq_resume: ..." line. has_own/own_next are passed straight
115	 * to gt_next_seq. quiet hides connect errors (reconnect mode expects them
116	 * while storage is down). Returns the fd, or -1 on any failure. */
117	static int open_session(const char *path, int quiet, int has_own,
118	                        uint32_t own_next, uint32_t *next_out)
119	{
120	    int fd = connect_storage(path, quiet);
121	    gt_resume resume;
122	    if (fd < 0 || !read_resume(fd, &resume)) {
123	        if (fd >= 0) {
124	            close(fd);
125	        }
126	        return -1;
127	    }
128	    if (gt_next_seq(has_own, own_next, &resume, next_out) != GT_OK) {
129	        fprintf(stderr, "storage_feed: no next seq after %lu\n", (unsigned long)resume.seq);
130	        close(fd);
131	        return -1;
132	    }
133	    if (resume.has_last) {
134	        printf("seq_resume: last=%lu, sending from %lu\n", (unsigned long)resume.seq,
135	               (unsigned long)*next_out);
136	    } else {
137	        printf("seq_resume: empty log, sending from %lu\n", (unsigned long)*next_out);
138	    }
139	    return fd;
140	}
141	
142	/* Wall-clock time in us since the epoch, stamped into each record as the
143	 * hub would. */
144	static uint64_t wall_us(void)
145	{
146	    struct timespec now;
147	    clock_gettime(CLOCK_REALTIME, &now);
148	    return (uint64_t)now.tv_sec * 1000000u + (uint64_t)now.tv_nsec / 1000u;
149	}
150	
151	/* What one pass of the send loop came to. An enum gives names to a small
152	 * set of int values, so the caller compares against FEED_STOP rather than
153	 * a bare number. */
154	typedef enum { FEED_SENT, FEED_RETRY, FEED_STOP } feed_result;
155	
156	/* Everything the send loop changes as it goes, in one struct so a helper
157	 * can update it through a single pointer. */
158	typedef struct {
159	    int           fd;          /* the connection to storage; -1 if none */
160	    uint32_t      own_next;    /* the next seq to send */
161	    uint32_t      first_seq;   /* the first seq sent (valid once sent > 0) */
162	    unsigned long sent;        /* records sent, over all connections */
163	} feed_state;
164	
165	/* One pass of the send loop: connect first if there is no connection
166	 * (only with -r), then send the record with seq state->own_next.
167	 *   FEED_SENT:  it went; own_next and sent moved on.
168	 *   FEED_RETRY: storage is not up yet or went away (only with -r); the
169	 *               next pass reconnects.
170	 *   FEED_STOP:  give up: a send failed without -r, or encoding failed. */
171	static feed_result send_next(feed_state *state, const char *sock_path, int reconnect)
172	{
173	    if (state->fd < 0) {
174	        state->fd = open_session(sock_path, 1, state->sent > 0, state->own_next,
175	                                 &state->own_next);
176	        if (state->fd < 0) {
177	            const struct timespec retry_wait = { 0, 100000000L }; /* 100 ms */
178	            nanosleep(&retry_wait, NULL);
179	            return FEED_RETRY;
180	        }
181	    }
182	    const gt_record record = {
183	        .type = GT_REC_DATA, .sensor_id = GT_SENSOR_LIGHT,
184	        .seq = state->own_next, .timestamp_us = wall_us(),
185	        .value = (uint32_t)state->sent,
186	    };
187	    uint8_t wire[GT_REC_SIZE];
188	    if (gt_record_encode(&record, wire) != GT_OK) {
189	        fprintf(stderr, "storage_feed: encode seq %lu failed\n", (unsigned long)record.seq);
190	        return FEED_STOP;
191	    }
192	    if (send(state->fd, wire, sizeof wire, MSG_NOSIGNAL) != (ssize_t)sizeof wire) {
193	        if (!reconnect) {
194	            fprintf(stderr, "storage_feed: send seq %lu: %s\n",
195	                    (unsigned long)record.seq, strerror(errno));
196	            return FEED_STOP;
197	        }
198	        if (state->sent > 0) {
199	            printf("storage gone after seq %lu\n", (unsigned long)(state->own_next - 1));
200	        } else {
201	            printf("storage gone before any seq\n");
202	        }
203	        close(state->fd);
204	        state->fd = -1;
205	        return FEED_RETRY;
206	    }
207	    if (state->sent == 0) {
208	        state->first_seq = state->own_next;
209	    }
210	    state->own_next++;
211	    state->sent++;
212	    return FEED_SENT;
213	}
214	
215	int main(int argc, char **argv)
216	{
217	    /* _IOLBF = line buffering: flush stdout at every '\n', even when it is
218	     * redirected to a file (the default there is to hold it until exit). */
219	    setvbuf(stdout, NULL, _IOLBF, 0);
220	    /* No SA_RESTART: a stop signal cuts nanosleep/poll short (EINTR), so
221	     * the loop sees stop_requested at once. */
222	    struct sigaction stop_action;
223	    memset(&stop_action, 0, sizeof stop_action);
224	    stop_action.sa_handler = on_stop;
225	    sigemptyset(&stop_action.sa_mask);
226	    sigaction(SIGTERM, &stop_action, NULL);
227	    sigaction(SIGINT, &stop_action, NULL);
228	    /* -r, if given, comes first; arg_base is then the index of SOCK. */
229	    int reconnect = argc > 1 && strcmp(argv[1], "-r") == 0;
230	    int arg_base = reconnect ? 2 : 1;
231	    int args_left = argc - arg_base;
232	    unsigned long count = 0, rate_hz = 10;
233	    if ((args_left != 2 && args_left != 3) || !parse_count(argv[arg_base + 1], &count)
234	        || (args_left == 3 && !parse_count(argv[arg_base + 2], &rate_hz))) {
235	        fprintf(stderr, "usage: %s [-r] /run/plantpi/storage.sock COUNT [RATE_HZ]\n",
236	                argv[0]);
237	        return 2;
238	    }
239	    const char *sock_path = argv[arg_base];
240	
241	    struct timespec gap = { 0, 0 };
242	    if (rate_hz > 0) {
243	        gap.tv_sec = (time_t)(1 / rate_hz);
244	        gap.tv_nsec = (long)((1000000000ul / rate_hz) % 1000000000ul);
245	    }
246	    feed_state state = { .fd = -1, .own_next = 0, .first_seq = 0, .sent = 0 };
247	    if (!reconnect) {
248	        state.fd = open_session(sock_path, 0, 0, 0, &state.own_next);
249	        if (state.fd < 0) {
250	            return 1;
251	        }
252	    }
253	    /* invariant: every seq below state.own_next was sent exactly once; none
254	     * is reused */
255	    while (!stop_requested && ((reconnect && count == 0) || state.sent < count)) {
256	        feed_result result = send_next(&state, sock_path, reconnect);
257	        if (result == FEED_STOP) {
258	            break;
259	        }
260	        if (result == FEED_SENT && rate_hz > 0) {
261	            nanosleep(&gap, NULL);
262	        }
263	    }
264	    if (state.sent > 0) {
265	        printf("sent %lu records, seq %lu..%lu\n", state.sent, (unsigned long)state.first_seq,
266	               (unsigned long)(state.own_next - 1));
267	    } else {
268	        printf("sent 0 records\n");
269	    }
270	    if (state.fd >= 0) {
271	        close(state.fd);
272	    }
273	    return (state.sent == count || (reconnect && stop_requested)) ? 0 : 1;
274	}
