1	/* light_probe: on-Pi bring-up check for the BH1750 light sensor.
2	 *
3	 * Purpose: the unit tests prove the driver against a fake bus; this program
4	 * proves the real hardware path, which no test on a dev machine can reach.
5	 * It runs the same driver code the light_sensor process will use and prints
6	 * a PASS/FAIL checklist, exiting nonzero if any check fails:
7	 *   1. the I2C bus device opens        (I2C enabled, permissions OK)
8	 *   2. a BH1750 ACKs at 0x23           (wiring, ADDR pin, power)
9	 *   3. one measurement reads           (basic C read, raw count + lux)
10	 *   4. N samples on a fixed period     (sampling interval and jitter)
11	 *
12	 * Linux model: /dev/i2c-1 exists only once I2C is enabled (raspi-config ->
13	 * Interface Options -> I2C), and opening it needs root or the `i2c` group.
14	 * Opening the bus and selecting an address succeed even with nothing wired,
15	 * so check 2 is the first point that proves a device is really there.
16	 *
17	 * Usage: light_probe [-d /dev/i2c-1] [-n samples] [-p period_ms]
18	 * Wiring (Pi header): VCC -> 3.3V pin 1, GND -> pin 6, SDA -> GPIO2 pin 3,
19	 * SCL -> GPIO3 pin 5, ADDR -> GND or unconnected (0x23; 3.3V gives 0x5C). */
20	#include <errno.h>
21	#include <stdio.h>
22	#include <stdlib.h>
23	#include <string.h>
24	#include <time.h>
25	#include <unistd.h>
26	
27	#include "i2c_bus.h"
28	#include "light_sensor.h"
29	
30	typedef struct {
31	    const char *dev;
32	    int         samples;
33	    long        period_ms;
34	} probe_opts;
35	
36	/* Print one checklist line, e.g. "[2/4] BH1750 answers at 0x23 ... PASS". */
37	static void report(int step, const char *what, int ok)
38	{
39	    printf("[%d/4] %-34s %s\n", step, what, ok ? "PASS" : "FAIL");
40	}
41	
42	/* Parse -d/-n/-p into `o`. Returns 0, or -1 after printing usage. */
43	static int parse_opts(int argc, char **argv, probe_opts *o)
44	{
45	    o->dev = "/dev/i2c-1";
46	    o->samples = 60;
47	    o->period_ms = 1000;
48	
49	    int c;
50	    while ((c = getopt(argc, argv, "d:n:p:")) != -1) {
51	        switch (c) {
52	        case 'd': o->dev = optarg; break;
53	        case 'n': o->samples = atoi(optarg); break;
54	        case 'p': o->period_ms = atol(optarg); break;
55	        default:  goto usage;
56	        }
57	    }
58	    /* The period must outlast one high-res conversion, or reads would return
59	     * the same measurement twice. */
60	    if (o->samples < 2 || o->period_ms < GT_BH1750_MEAS_MAX_MS) {
61	        goto usage;
62	    }
63	    return 0;
64	
65	usage:
66	    fprintf(stderr, "usage: %s [-d /dev/i2c-1] [-n samples>=2] [-p period_ms>=%d]\n",
67	            argv[0], GT_BH1750_MEAS_MAX_MS);
68	    return -1;
69	}
70	
71	/* Check 1: open the bus and bind GT_LIGHT_I2C_ADDR. On failure, explain the
72	 * likely cause from errno (open() is the call that fails here). */
73	static int check_bus(const char *dev, gt_i2c_bus *bus)
74	{
75	    errno = 0;
76	    int ok = gt_i2c_linux_open(dev, GT_LIGHT_I2C_ADDR, bus) == GT_OK;
77	    report(1, "I2C bus opens", ok);
78	    if (!ok) {
79	        int e = errno;
80	        fprintf(stderr, "      %s: %s\n", dev, e ? strerror(e) : "open failed");
81	        if (e == ENOENT) {
82	            fprintf(stderr, "      hint: enable I2C (sudo raspi-config -> Interface Options -> I2C), reboot\n");
83	        } else if (e == EACCES) {
84	            fprintf(stderr, "      hint: sudo usermod -aG i2c $USER, then log out and back in\n");
85	        }
86	    }
87	    return ok;
88	}
89	
90	/* Check 2: initialise the sensor. The driver's POWER_ON write is the first
91	 * real bus transaction, so a NULL here means nothing ACKed at 0x23. The
92	 * driver owns `bus` from here on and closes it on failure. */
93	static gt_light_sensor *check_device(gt_i2c_bus bus)
94	{
95	    gt_light_sensor *s = gt_light_open_bus(bus);
96	    report(2, "BH1750 answers at 0x23", s != NULL);
97	    if (s == NULL) {
98	        fprintf(stderr, "      hint: run `i2cdetect -y 1`; expect 23. Nothing shown -> check wiring/power;\n"
99	                        "            5c shown -> ADDR pin is high, tie it to GND\n");
100	    }
101	    return s;
102	}
103	
104	/* Check 3: one measurement through the driver, printed as raw and lux. */
105	static int check_read(gt_light_sensor *s)
106	{
107	    uint32_t raw = 0;
108	    int ok = gt_light_read(s, &raw) == GT_OK;
109	    report(3, "single read", ok);
110	    if (ok) {
111	        printf("      raw=%u  lux=%.1f\n", (unsigned)raw, gt_light_raw_to_lux(raw));
112	    } else {
113	        fprintf(stderr, "      read failed after %d retries\n", GT_LIGHT_RETRIES);
114	    }
115	    return ok;
116	}
117	
118	/* Sampling jitter target from DESIGN.md ("Sampling jitter": p99 < 10 ms). */
119	#define JITTER_P99_LIMIT_US 10000
120	
121	static int64_t mono_us(void)
122	{
123	    struct timespec t;
124	    clock_gettime(CLOCK_MONOTONIC, &t);
125	    return (int64_t)t.tv_sec * 1000000 + t.tv_nsec / 1000;
126	}
127	
128	/* Sleep until absolute CLOCK_MONOTONIC time `us`. Absolute deadlines keep
129	 * the schedule from drifting: a late wake-up doesn't push later samples
130	 * back, as a relative sleep(period) after each read would. */
131	static void sleep_until_us(int64_t us)
132	{
133	    struct timespec t = { .tv_sec = us / 1000000, .tv_nsec = (long)(us % 1000000) * 1000 };
134	    /* clock_nanosleep returns the error number itself, not -1/errno. */
135	    while (clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &t, NULL) == EINTR) {
136	    }
137	}
138	
139	static int cmp_i64(const void *a, const void *b)
140	{
141	    int64_t x = *(const int64_t *)a, y = *(const int64_t *)b;
142	    return (x > y) - (x < y);
143	}
144	
145	/* Nearest-rank percentile of a sorted array, e.g. pct = 99. */
146	static int64_t percentile(const int64_t *sorted, int n, int pct)
147	{
148	    int rank = (pct * n + 99) / 100;   /* ceil(pct/100 * n) */
149	    return sorted[rank > 0 ? rank - 1 : 0];
150	}
151	
152	/* Check 4: take `n` samples, one per `period_ms`, on an absolute schedule.
153	 * Each sample is timestamped just before its I2C read, which is the point
154	 * DESIGN.md measures jitter at. Prints every sample so lux can be watched
155	 * live (cover the sensor, shine a light), then a summary. Passes if every
156	 * read succeeded and p99 deviation from the schedule is under 10 ms. */
157	static int check_sampling(gt_light_sensor *s, int n, long period_ms)
158	{
159	    int64_t *dev_us = malloc((size_t)n * sizeof *dev_us);
160	    if (dev_us == NULL) {
161	        report(4, "sampling interval", 0);
162	        return 0;
163	    }
164	
165	    int64_t period_us = (int64_t)period_ms * 1000;
166	    int64_t start = mono_us() + period_us;
167	    int64_t prev = 0, ivl_min = INT64_MAX, ivl_max = 0, ivl_sum = 0;
168	    uint32_t raw_min = UINT32_MAX, raw_max = 0;
169	    double lux_sum = 0;
170	    int errors = 0, good = 0;
171	
172	    printf("      sampling %d x %ld ms (cover the sensor / shine a light to see lux follow)\n",
173	           n, period_ms);
174	    printf("      %4s %10s %7s %9s %8s\n", "i", "t_ms", "raw", "lux", "dev_us");
175	
176	    for (int i = 0; i < n; i++) {
177	        int64_t deadline = start + i * period_us;
178	        sleep_until_us(deadline);
179	        int64_t now = mono_us();
180	        dev_us[i] = now - deadline;   /* >= 0: wake-ups are never early */
181	
182	        if (i > 0) {
183	            int64_t ivl = now - prev;
184	            ivl_min = ivl < ivl_min ? ivl : ivl_min;
185	            ivl_max = ivl > ivl_max ? ivl : ivl_max;
186	            ivl_sum += ivl;
187	        }
188	        prev = now;
189	
190	        uint32_t raw;
191	        double t_ms = (double)(now - start) / 1000.0;
192	        if (gt_light_read(s, &raw) != GT_OK) {
193	            errors++;
194	            printf("      %4d %10.1f %7s %9s %8lld\n", i, t_ms, "ERR", "-", (long long)dev_us[i]);
195	            continue;
196	        }
197	        good++;
198	        raw_min = raw < raw_min ? raw : raw_min;
199	        raw_max = raw > raw_max ? raw : raw_max;
200	        lux_sum += gt_light_raw_to_lux(raw);
201	        printf("      %4d %10.1f %7u %9.1f %8lld\n", i, t_ms, (unsigned)raw,
202	               gt_light_raw_to_lux(raw), (long long)dev_us[i]);
203	    }
204	
205	    qsort(dev_us, (size_t)n, sizeof *dev_us, cmp_i64);
206	    int64_t p50 = percentile(dev_us, n, 50);
207	    int64_t p99 = percentile(dev_us, n, 99);
208	    int64_t dmax = dev_us[n - 1];
209	    free(dev_us);
210	
211	    int ok = errors == 0 && p99 < JITTER_P99_LIMIT_US;
212	    report(4, "sampling interval", ok);
213	    printf("      reads:    %d ok, %d failed\n", good, errors);
214	    if (good > 0) {
215	        printf("      lux:      min %.1f  mean %.1f  max %.1f\n",
216	               gt_light_raw_to_lux(raw_min), lux_sum / good, gt_light_raw_to_lux(raw_max));
217	    }
218	    printf("      interval: min %.3f  mean %.3f  max %.3f ms (target %ld)\n",
219	           ivl_min / 1000.0, ivl_sum / 1000.0 / (n - 1), ivl_max / 1000.0, period_ms);
220	    printf("      jitter:   p50 %lld  p99 %lld  max %lld us (p99 limit %d)\n",
221	           (long long)p50, (long long)p99, (long long)dmax, JITTER_P99_LIMIT_US);
222	
223	    /* Not a FAIL: a dark closet really is constant. But a stuck 0 or 65535
224	     * often means a dead or saturated sensor, so make the user look. */
225	    if (good >= 2 && raw_min == raw_max) {
226	        printf("      warning: every sample read raw=%u; vary the light and rerun\n",
227	               (unsigned)raw_min);
228	    }
229	    return ok;
230	}
231	
232	int main(int argc, char **argv)
233	{
234	    /* Line-buffer stdout so PASS/FAIL lines and stderr hints stay in order
235	     * even when the output is piped to a log (e.g. `| tee probe.log`). */
236	    setvbuf(stdout, NULL, _IOLBF, 0);
237	
238	    probe_opts o;
239	    if (parse_opts(argc, argv, &o) != 0) {
240	        return 2;
241	    }
242	
243	    gt_i2c_bus bus;
244	    if (!check_bus(o.dev, &bus)) {
245	        return 1;
246	    }
247	    gt_light_sensor *s = check_device(bus);
248	    if (s == NULL) {
249	        return 1;
250	    }
251	    int ok = check_read(s) && check_sampling(s, o.samples, o.period_ms);
252	
253	    gt_light_close(s);
254	    return ok ? 0 : 1;
255	}
